def longest_parity_balance(values):
    """
    Finds the length of the longest nonempty contiguous range in the given list
    that contains equally many even and odd values. Returns 0 if no such range exists.

    :param values: List of integers
    :return: Length of the longest balanced range or 0 if none exists
    """
    balance = 0
    balance_map = {0: -1}
    max_length = 0

    for i, value in enumerate(values):
        if value % 2 == 0:
            balance -= 1
        else:
            balance += 1

        if balance not in balance_map:
            balance_map[balance] = i
        else:
            max_length = max(max_length, i - balance_map[balance])

    return max_length
