def can_two_color(nodes, edges):
    """
    Determines if the given graph can be colored with two colors such that no two adjacent nodes have the same color.

    Parameters:
    nodes (set): A set of nodes in the graph.
    edges (set): A set of tuples representing undirected edges between nodes.

    Returns:
    bool: True if the graph can be two-colored, False otherwise.
    """
    color = {}

    def dfs(node):
        for neighbor in edges:
            if node in neighbor:
                if node == neighbor[0]:
                    other = neighbor[1]
                else:
                    other = neighbor[0]
                if other in color:
                    if color[other] == color[node]:
                        return False
                else:
                    color[other] = 1 - color[node]
                    if not dfs(other):
                        return False
        return True

    for node in nodes:
        if node not in color:
            color[node] = 0
            if not dfs(node):
                return False
    return True
