    """
    Identify articulation points in a connected undirected graph.

    An articulation point (or cut vertex) is a vertex whose removal increases
    the number of connected components in the graph. This function returns
    a sorted list of such vertices.

    Parameters:
    nodes (list): A list of nodes in the graph.
    edges (list of tuples): A list of edges, where each edge is represented as a tuple (node1, node2).

    Returns:
    list: A sorted list of articulation points.
    """
    def build_adjacency_list(nodes, edges):
        adj_list = {node: [] for node in nodes}
        for edge in edges:
            adj_list[edge[0]].append(edge[1])
            adj_list[edge[1]].append(edge[0])
        return adj_list

    def dfs(node, adj_list, visited, disc, low, parent, ap, time):
        visited[node] = True
        disc[node] = low[node] = time[0]
        time[0] += 1

        child_count = 0
        for neighbor in adj_list[node]:
            if not visited[neighbor]:
