def multiset_difference(text: str, remove: str) -> str:
    """
    Consume the requested character counts from left to right in text, skipping exactly those consumed occurrences
    and preserving every other character. Return None if remove requests a character too many times.

    :param text: The input string from which characters are to be removed.
    :param remove: The string containing characters to be removed from the input string.
    :return: The resulting string after removing characters as specified, or None if an invalid request is made.
    """
    # Create a dictionary to count occurrences of each character in 'remove'
    remove_counts = {}
    for char in remove:
        if char in remove_counts:
            remove_counts[char] += 1
        else:
            remove_counts[char] = 1

    # Iterate over the input text and build the result string
    result = []
    for char in text:
        if char in remove_counts and remove_counts[char] > 0:
            remove_counts[char] -= 1
        else:
            result.append(char)

    # Check if all characters in 'remove' were consumed correctly
    for count in remove_counts.values():
        if count > 0:
            return None

    return ''.join(result)
