def tree_cover_size(nodes, edges):
    """
    Given a tree represented by a list of nodes and a list of edges, this function returns the minimum number of vertices
    whose selected set contains at least one endpoint of every edge. This is also known as the vertex cover of the tree.

    Parameters:
    nodes (list): A list of unique node identifiers.
    edges (list of tuples): A list of edges, where each edge is represented as a tuple of two node identifiers.

    Returns:
    int: The size of the minimum vertex cover of the tree.
    """
    if not edges:
        return len(nodes)  # If there are no edges, all nodes are needed to cover the tree.

    # Create a graph representation using adjacency list
    graph = {node: [] for node in nodes}
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    # Depth-first search to find a minimum vertex cover
    visited = set()
    cover = set()

    def dfs(node, parent):
        visited.add(node)
        for neighbor in graph[node]:
            if neighbor != parent and neighbor not in visited:
                dfs(neighbor, node)
        if parent is None and len(graph[node]) % 2 == 0:
            cover.add(node)

    for node in nodes:
        if node not in visited:
            dfs(node, None)

    return len(cover)
